"""Replay only explicitly reviewed accounting equations, not arbitrary mixed-type sums."""
import hashlib,json,re
from review_receipts import validate_receipt
KEYS={'top': ['attribution', 'checks', 'id', 'limits', 'publication', 'records', 'retrievedAt', 'schemaVersion', 'simpleExplanation', 'sourceSha256', 'sourceURL', 'status', 'title'], 'publication': ['allowed', 'consequentialAllegation', 'reviewId', 'reviewType', 'reviewedOn'], 'row': ['aggregationRole', 'asOf', 'currency', 'currencyBasis', 'currencyExplicitlySpecified', 'fiscalYear', 'id', 'individualPaymentEvidence', 'label', 'measureType', 'multiplier', 'periodEnd', 'periodStart', 'rawToken', 'rawValue', 'section', 'sourceLocator', 'stage', 'unit'], 'locator': ['columnAsReported', 'pdfPage', 'printedPage', 'rowLabel'], 'check': ['annualResult', 'annualResultRecordId', 'closingCash', 'equations', 'exactEquationsVerified', 'fiscalYear', 'netCashChange', 'openingCash', 'unexplainedArithmeticResidual'], 'equation': ['calculated', 'id', 'inputRecordIds', 'operation', 'outputRecordId', 'reported', 'residual']}
ROLES={'cash_flow|Annual (deficit) surplus': ['accrual_result', 'component'], 'cash_flow|Amortization of tangible capital assets': ['reconciliation_adjustment', 'component'], 'cash_flow|Employee future benefit obligations': ['reconciliation_adjustment', 'component'], 'cash_flow|Provincial receivable - future health benefits': ['reconciliation_adjustment', 'component'], 'cash_flow|Accrued obligation for other compensated absences': ['reconciliation_adjustment', 'component'], 'cash_flow|Changes in non-cash working capital (Note 9)': ['reconciliation_adjustment', 'component'], 'cash_flow|Operating subtotal': ['cash_flow', 'subtotal'], 'cash_flow|Purchase of tangible capital assets': ['cash_flow', 'component'], 'cash_flow|Capital subtotal': ['cash_flow', 'subtotal'], 'cash_flow|Proceeds on the sale of investments': ['cash_flow', 'component'], 'cash_flow|Purchase of investments': ['cash_flow', 'component'], 'cash_flow|Net purchase of investments - Foundation': ['cash_flow', 'component'], 'cash_flow|Investing subtotal': ['cash_flow', 'subtotal'], 'cash_flow|Net (decrease) increase in cash': ['cash_flow', 'balance'], 'cash_flow|Cash, beginning of year': ['stock', 'opening_balance'], 'cash_flow|Cash, end of year': ['stock', 'closing_balance'], 'working_capital|Accounts receivable': ['reconciliation_adjustment', 'component'], 'working_capital|Inventory for resale': ['reconciliation_adjustment', 'component'], 'working_capital|Prepaid expenses': ['reconciliation_adjustment', 'component'], 'working_capital|Accounts payable and accrued liabilities - operating': ['reconciliation_adjustment', 'component'], 'working_capital|Deferred revenue - restricted funding': ['reconciliation_adjustment', 'component'], 'working_capital|Deferred revenue - Foundation': ['reconciliation_adjustment', 'component'], 'working_capital|Changes in non-cash working capital from operations': ['reconciliation_adjustment', 'subtotal']}
GRAPHS={'operating': {'inputs': ['cash_flow|Annual (deficit) surplus', 'cash_flow|Amortization of tangible capital assets', 'cash_flow|Employee future benefit obligations', 'cash_flow|Provincial receivable - future health benefits', 'cash_flow|Accrued obligation for other compensated absences', 'cash_flow|Changes in non-cash working capital (Note 9)'], 'output': 'cash_flow|Operating subtotal'}, 'capital': {'inputs': ['cash_flow|Purchase of tangible capital assets'], 'output': 'cash_flow|Capital subtotal'}, 'investing': {'inputs': ['cash_flow|Proceeds on the sale of investments', 'cash_flow|Purchase of investments', 'cash_flow|Net purchase of investments - Foundation'], 'output': 'cash_flow|Investing subtotal'}, 'net_cash': {'inputs': ['cash_flow|Operating subtotal', 'cash_flow|Capital subtotal', 'cash_flow|Investing subtotal'], 'output': 'cash_flow|Net (decrease) increase in cash'}, 'cash_balance': {'inputs': ['cash_flow|Cash, beginning of year', 'cash_flow|Net (decrease) increase in cash'], 'output': 'cash_flow|Cash, end of year'}, 'working_capital': {'inputs': ['working_capital|Accounts receivable', 'working_capital|Inventory for resale', 'working_capital|Prepaid expenses', 'working_capital|Accounts payable and accrued liabilities - operating', 'working_capital|Deferred revenue - restricted funding', 'working_capital|Deferred revenue - Foundation'], 'output': 'working_capital|Changes in non-cash working capital from operations'}, 'note_to_statement': {'inputs': ['working_capital|Changes in non-cash working capital from operations'], 'output': 'cash_flow|Changes in non-cash working capital (Note 9)'}}
def shape(v,key):
    if not isinstance(v,dict) or sorted(v)!=KEYS[key]:raise ValueError('Unexpected cash-bridge fields')
def record_key(r):return r['section']+'|'+r['label']
def cash_files(root):
    folder=root/'data/cash-bridge';path=folder/'case.json'
    if not path.exists():return []
    review=validate_receipt(json.loads((folder/'publication-review.json').read_text()),'foundation')
    if hashlib.sha256(path.read_bytes()).hexdigest()!=review['bundleSha256']:raise ValueError('Cash-bridge review hash mismatch')
    b=json.loads(path.read_text());shape(b,'top');shape(b['publication'],'publication');p=b['publication']
    if b['schemaVersion']!='nscc-cash-bridge-v1' or b['status']!='explained_by_verified_statement_arithmetic' or p['allowed'] is not True or p['consequentialAllegation'] is not False or p['reviewType']!='published_internal_accounting_reconciliation' or p['reviewId']!=review['evidenceId'] or p['reviewedOn']!=review['reviewedOn']:raise ValueError('Unreviewed accounting case')
    statement=json.loads((root/'data/nscc/records.json').read_text());originals={r['id']:r for r in statement['records']}
    if b['sourceSha256']!=statement['sourceSha256']:raise ValueError('Different institutional source')
    rows={};identities=set()
    for r in b['records']:
        shape(r,'row');shape(r['sourceLocator'],'locator');identity=(r['fiscalYear'],record_key(r))
        if r['id'] in rows or identity in identities or ROLES.get(record_key(r))!=[r['measureType'],r['aggregationRole']]:raise ValueError('Invalid accounting type or identity')
        rows[r['id']]=r;identities.add(identity);start=int(r['fiscalYear'][:4]);end=start+1
        if r['fiscalYear'] not in ('2025-26','2024-25') or r['stage']!=('audited_statement_actual' if start==2025 else 'prior_year_comparative_as_presented') or r['sourceLocator']['columnAsReported']!=str(end) or r['sourceLocator']['rowLabel']!=r['label'] or r['sourceLocator']['pdfPage']!={'cash_flow':10,'working_capital':17}[r['section']]:raise ValueError('Cash source period mismatch')
        if r['measureType']=='stock':
            if r['asOf']!=f"{start if r['aggregationRole']=='opening_balance' else end}-03-31" or r['periodStart'] is not None or r['periodEnd'] is not None:raise ValueError('Cash stock date mismatch')
        elif r['asOf'] is not None or r['periodStart']!=f'{start}-04-01' or r['periodEnd']!=f'{end}-03-31':raise ValueError('Cash flow period mismatch')
        if r['currency']!='CAD' or r['currencyExplicitlySpecified'] is not False or r['currencyBasis']!='context_inferred_from_canadian_public_sector_financial_statement' or r['multiplier']!=1 or r['unit']!='source_dollars' or r['individualPaymentEvidence'] is not False or not re.fullmatch(r'-?\d+',r['rawValue']):raise ValueError('Unsupported cash claim')
        token=r['rawToken'].replace(',','');token='-'+token[1:-1] if token.startswith('(') and token.endswith(')') else token
        if token!=r['rawValue']:raise ValueError('Cash token mismatch')
    years=set();equations=set()
    for check in b['checks']:
        shape(check,'check');year=check['fiscalYear']
        if year in years or year not in ('2025-26','2024-25'):raise ValueError('Duplicate or wrong cash year')
        years.add(year);original=originals.get(check['annualResultRecordId'])
        annual=next(r for r in rows.values() if r['fiscalYear']==year and r['label']=='Annual (deficit) surplus')
        if not original or original['fiscalYear']!=year or original['label']!='Annual (deficit) surplus' or original['stage']!=annual['stage'] or original['measureType']!='flow' or original['periodStart']!=annual['periodStart'] or original['periodEnd']!=annual['periodEnd'] or original['rawValue']!=check['annualResult'] or annual['rawValue']!=check['annualResult']:raise ValueError('Annual result source link mismatch')
        for eq in check['equations']:
            shape(eq,'equation');kind=eq['id'].rsplit('-',2)[0];graph=GRAPHS.get(kind);inputs=[rows.get(i) for i in eq['inputRecordIds']];output=rows.get(eq['outputRecordId'])
            if not graph or eq['id']!=kind+'-'+year or eq['id'] in equations or eq['operation']!='sum_equals' or len(set(eq['inputRecordIds']))!=len(inputs) or not output or any(not r or r['fiscalYear']!=year for r in inputs+[output]) or [record_key(r) for r in inputs]!=graph['inputs'] or record_key(output)!=graph['output']:raise ValueError('Equation graph mismatch')
            equations.add(eq['id']);total=sum(int(r['rawValue']) for r in inputs);reported=int(output['rawValue'])
            if str(total)!=eq['calculated'] or str(reported)!=eq['reported'] or str(total-reported)!=eq['residual'] or eq['residual']!='0':raise ValueError('Unreconciled published equation')
        for field,label in [('openingCash','Cash, beginning of year'),('closingCash','Cash, end of year'),('netCashChange','Net (decrease) increase in cash')]:
            if check[field]!=next(r['rawValue'] for r in rows.values() if r['fiscalYear']==year and r['label']==label):raise ValueError('Cash summary mismatch')
        if len(check['equations'])!=7 or check['exactEquationsVerified']!=7 or check['unexplainedArithmeticResidual']!='0':raise ValueError('Incomplete accounting checks')
    if len(years)!=2 or len(rows)!=46 or len(equations)!=14:raise ValueError('Incomplete cash-bridge scope')
    return ['data/cash-bridge/case.json','data/cash-bridge/publication-review.json']
